def solution(items):
    n = len(items)
    if n < 2:
        return 0

    def sort_count(arr):
        m = len(arr)
        if m <= 1:
            return arr, 0
        mid = m // 2
        left, inv_l = sort_count(arr[:mid])
        right, inv_r = sort_count(arr[mid:])
        merged = []
        i = j = 0
        inv = inv_l + inv_r
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                inv += len(left) - i
                j += 1
        if i < len(left):
            merged.extend(left[i:])
        if j < len(right):
            merged.extend(right[j:])
        return merged, inv

    _, inversions = sort_count(items)
    total_pairs = n * (n - 1) // 2
    return total_pairs - inversions
